B.ayc=new A.bB("kanun_08",B.fg,"Hukuk mahkemeleri taraf\u0131ndan verilen nihai kararlara kar\u015f\u0131, karar\u0131n usul\xfcne uygun tebli\u011finden itibaren kural olarak ka\xe7 hafta i\xe7inde istinaf yoluna ba\u015fvurulabilir?",B.tg,1,"HMK m. 345 uyar\u0131nca istinaf yoluna ba\u015fvuru s\xfcresi, karar\u0131n usul\xfcne uygun olarak taraflara tebli\u011finden itibaren iki haftad\u0131r.")
B.aoU=s(["Miktar veya de\u011feri temyiz s\u0131n\u0131r\u0131n\u0131 a\u015fan alacak davalar\u0131","Soyba\u011f\u0131na ili\u015fkin kararlar","\xc7eki\u015fmesiz yarg\u0131 i\u015flerinde verilen kararlar","Ta\u015f\u0131nmaz \xfczerindeki ayni haklara ili\u015fkin kararlar"],t.s)
B.ayr=new A.bB("kanun_09",B.fg,"B\xf6lge adliye mahkemesi hukuk dairelerinden verilen a\u015fa\u011f\u0131daki kararlardan hangisine kar\u015f\u0131 kural olarak temyiz yoluna ba\u015fvurulamaz?",B.aoU,2,"HMK m. 362/1-\xe7 bendine g\xf6re \xe7eki\u015fmesiz yarg\u0131 i\u015flerinde verilen b\xf6lge adliye mahkemesi kararlar\u0131 kesin olup bu kararlara kar\u015f\u0131 temyiz yoluna ba\u015fvurulamaz.")
B.akL=s(["Feragat, h\xfck\xfcm kesinle\u015finceye kadar her zaman yap\u0131labilir.","Feragatin ge\xe7erlili\u011fi kar\u015f\u0131 taraf\u0131n veya mahkemenin kabul\xfcne ba\u011fl\u0131d\u0131r.","Feragat, kesin h\xfck\xfcm gibi hukuki sonu\xe7 do\u011furur.","\u015earta ba\u011fl\u0131 feragat kural olarak ge\xe7erli de\u011fildir."],t.s)
B.ay2=new A.bB("taraf_08",B.ff,'Davac\u0131n\u0131n talep sonucundan k\u0131smen veya tamamen vazge\xe7mesi olan "feragat" kurumu ile ilgili a\u015fa\u011f\u0131dakilerden hangisi yanl\u0131\u015ft\u0131r?',B.akL,1,"HMK m. 309 uyar\u0131nca feragat ve kabul, kar\u015f\u0131 taraf\u0131n veya mahkemenin muvafakatine ba\u011fl\u0131 de\u011fildir; tek tarafl\u0131 irade beyan\u0131yla derhal sonu\xe7 do\u011furur.")
B.a_F=new A.h(1,0.8941176470588236,0.6039215686274509,0.8235294117647058,B.d)
B.axW=new A.r0("H\xfck\xfcm ve Kesin H\xfck\xfcm",B.a_F,5,"hukumKesinHuku")
B.ab8=s(["Sadece taraflar\u0131n\u0131n","Sadece dava sebeplerinin","Taraflar\u0131n\u0131n, dava sebeplerinin ve ilk davan\u0131n h\xfck\xfcm f\u0131kras\u0131 ile ikinci davan\u0131n talep sonucunun","Sadece mahkemelerinin"],t.s)
B.ayA=new A.bB("hukum_01",B.axW,"Bir davada verilen karar\u0131n ba\u015fka bir davada maddi anlamda kesin h\xfck\xfcm te\u015fkil edebilmesi i\xe7in her iki davan\u0131n hangi unsurlar\u0131n\u0131n ayn\u0131 olmas\u0131 zorunludur?",B.ab8,2,"HMK m. 303/1 uyar\u0131nca maddi anlamda kesin h\xfck\xfcmden s\xf6z edilebilmesi i\xe7in her iki davan\u0131n taraflar\u0131n\u0131n, dava sebeplerinin (vak\u0131alar\u0131n) ve ilk davan\u0131n h\xfck\xfcm f\u0131kras\u0131 ile ikinci davan\u0131n talep sonucunun ayn\u0131 olmas\u0131 gerekir.")
B.abh=s(["Eksikli\u011fi gidermesi i\xe7in davac\u0131ya bir haftal\u0131k kesin s\xfcre verir.","Davay\u0131 esastan reddeder.","Davay\u0131, dava \u015fart\u0131 yoklu\u011fu sebebiyle usulden reddeder.","Davay\u0131 durdurur ve taraflar\u0131 arabulucuya g\xf6nderir."],t.s)
B.ay_=new A.bB("arabulucu_07",B.iQ,"Kanunlarda arabuluculu\u011fa ba\u015fvurulmu\u015f olmas\u0131n\u0131n dava \u015fart\u0131 olarak \xf6ng\xf6r\xfcld\xfc\u011f\xfc durumlarda, davac\u0131 arabulucuya ba\u015fvurmadan do\u011frudan dava a\xe7arsa mahkeme nas\u0131l bir karar verir?",B.abh,2,"6325 say\u0131l\u0131 Hukuk Uyu\u015fmazl\u0131klar\u0131nda Arabuluculuk Kanunu m. 18/A-2 uyar\u0131nca, arabulucuya ba\u015fvurulmadan dava a\xe7\u0131ld\u0131\u011f\u0131n\u0131n anla\u015f\u0131lmas\u0131 halinde herhangi bir i\u015flem yap\u0131lmaks\u0131z\u0131n davan\u0131n, dava \u015fart\u0131 yoklu\u011fu sebebiyle usulden reddine karar verilir.")
